import sys

class Book:
    def __init__(self, title, author):
        self.title = title
        self.author = author
        self.borrowed = False

class Library:
    def __init__(self):
        self.books = []

    def add_book(self, title, author):
        book = Book(title, author)
        self.books.append(book)
        return "Book added"

    def borrow_book(self, title):
        for book in self.books:
            if book.title == title and not book.borrowed:
                book.borrowed = True
                return "Book borrowed"
        return "Book not available"

    def return_book(self, title):
        for book in self.books:
            if book.title == title and book.borrowed:
                book.borrowed = False
                return "Book returned"
        return "Book returned"

def main():
    input = sys.stdin.read().strip().split('\n')
    if not input:
        return

    n = int(input[0])
    library = Library()

    for i in range(1, n + 1):
        if i >= len(input):
            break
        line = input[i].strip()
        if not line:
            continue

        parts = line.split()
        if not parts:
            continue

        operation = parts[0].lower() if parts else ""

        if operation == "add" and len(parts) >= 3:
            title = parts[1]
            author = ' '.join(parts[2:])
            print(library.add_book(title, author))
        elif operation == "borrow" and len(parts) >= 2:
            title = parts[1]
            print(library.borrow_book(title))
        elif operation == "return" and len(parts) >= 2:
            title = parts[1]
            print(library.return_book(title))

if __name__ == "__main__":
    main()
